1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	// What a single item of each type is worth to the MHPCO: what it costs to
59	// insure, and what it is insured for. Keeping the two figures side by side
60	// makes this the one place that says which item types exist at all.
61	interface ItemTypeRates {
62	  basePremium: number;
63	  insuranceValue: number;
64	}
65	
66	const ITEM_TYPE_RATES: Record<string, ItemTypeRates> = {
67	  sword: { basePremium: 100, insuranceValue: 1000 },
68	  amulet: { basePremium: 60, insuranceValue: 600 },
69	  staff: { basePremium: 80, insuranceValue: 800 },
70	  potion: { basePremium: 40, insuranceValue: 400 },
71	  rune: { basePremium: 25, insuranceValue: 250 },
72	  moonstone: { basePremium: 25, insuranceValue: 250 },
73	};
74	
75	const LOYALTY_YEARS_THRESHOLD = 2;
76	const LOYALTY_DISCOUNT_RATE = 0.2;
77	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
78	const CURSE_SURCHARGE_RATE = 0.5;
79	const HIGH_ENCHANTMENT_THRESHOLD = 5;
80	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	const DEDUCTIBLE = 100;
84	const CAP_MULTIPLIER = 2;
85	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
86	const REDUCED_REIMBURSEMENT_RATE = 0.5;
87	
88	// The MHPCO's price list is closed: anything not on it cannot be insured.
89	const ratesFor = (type: string): ItemTypeRates => {
90	  const rates = ITEM_TYPE_RATES[type];
91	  if (rates === undefined) {
92	    throw new Error(`the MHPCO does not insure items of type ${type}`);
93	  }
94	  return rates;
95	};
96	
97	const unitBasePremium = (type: string): number => ratesFor(type).basePremium;
98	
99	const countByType = (items: Item[]): Map<string, number> =>
100	  items.reduce(
101	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
102	    new Map<string, number>(),
103	  );
104	
105	// A building block of 3 alike components is offered at a special base premium.
106	const basePremiumForItemGroup = (type: string, count: number): number =>
107	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
112	    0,
113	  );
114	
115	// Premium-side enchantment rule (threshold 5), distinct from the claim-side
116	// reduced-reimbursement rule (threshold 8).
117	const qualifiesForHighEnchantmentSurcharge = (item: Item): boolean =>
118	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
119	
120	const surchargeRate = (item: Item): number =>
121	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
122	  (qualifiesForHighEnchantmentSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
123	
124	// Item-specific modifiers apply to the affected item's own base premium, i.e.
125	// the unit price of its type — a block discount never shrinks a surcharge.
126	const itemSurcharge = (item: Item): number =>
127	  unitBasePremium(item.type) * surchargeRate(item);
128	
129	const itemSurcharges = (items: Item[]): number =>
130	  items.reduce((total, item) => total + itemSurcharge(item), 0);
131	
132	const isLongStanding = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
134	
135	// Policy-wide modifiers apply to the policy base premium only — never to the
136	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
137	// Every quote is a first insurance for its items, regardless of customer
138	// history, so that surcharge always applies.
139	const policyAdjustmentRate = (
140	  customer: Customer,
141	  isFollowUpContract: boolean,
142	): number =>
143	  FIRST_INSURANCE_SURCHARGE_RATE -
144	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
145	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
146	
147	// Premiums round up, in the MHPCO's favour — once, over the whole sum, so
148	// intermediate amounts stay fractional. Rounding each term as it is computed
149	// would give a different answer: a base of 85 at a net rate of −10 % is
150	// 85 − 8.5 + 5 = 81.5 → 82, where rounding the −8.5 to −9 first yields 81.
151	//
152	// The policy adjustment is a signed rate applied to the base as its own term
153	// (`base + base * rate`) rather than a scale factor (`base * (1 + rate)`).
154	// Both express the same arithmetic, but the summed form avoids the rounding
155	// error a factor can carry: 100 * 1.1 === 110.00000000000001, while
156	// 100 + 100 * 0.1 === 110 exactly.
157	const quotePremium = (
158	  items: Item[],
159	  customer: Customer,
160	  isFollowUpContract: boolean,
161	): number => {
162	  const base = policyBasePremium(items);
163	  return Math.ceil(
164	    base +
165	      itemSurcharges(items) +
166	      base * policyAdjustmentRate(customer, isFollowUpContract) +
167	      PROCESSING_FEE,
168	  );
169	};
170	
171	const unitInsuranceValue = (type: string): number =>
172	  ratesFor(type).insuranceValue;
173	
174	// The total payout per policy is capped at twice the insurance sum. Premium
175	// modifiers never reach the insurance sum: it is the plain sum of the unit
176	// values of the insured items.
177	const insuranceSum = (items: Item[]): number =>
178	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
179	
180	// A policy created by a quote step, tracked so later claims can pay out
181	// against it. `remainingCap` shrinks as successive claims are settled.
182	interface Policy {
183	  items: Item[];
184	  remainingCap: number;
185	}
186	
187	const openPolicy = (items: Item[]): Policy => ({
188	  items,
189	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
190	});
191	
192	// State accumulated by the steps run so far. Later steps price and pay out
193	// against what earlier steps established, so each step reads the state it was
194	// run with and returns the state the next step should see.
195	interface ScenarioState {
196	  customer: Customer;
197	  contractsSoFar: number;
198	  // Keyed by the zero-based index of the quote step that created the policy.
199	  policies: Map<number, Policy>;
200	}
201	
202	// A step's outcome: what to report, and how the scenario stands afterwards.
203	interface StepOutcome {
204	  result: Result;
205	  state: ScenarioState;
206	}
207	
208	// Records a policy against the step index that identifies it, leaving the
209	// state it was given untouched.
210	const withPolicy = (
211	  state: ScenarioState,
212	  policyId: number,
213	  policy: Policy,
214	): ScenarioState => ({
215	  ...state,
216	  policies: new Map(state.policies).set(policyId, policy),
217	});
218	
219	const quote = (
220	  step: QuoteStep,
221	  state: ScenarioState,
222	  stepIndex: number,
223	): StepOutcome => ({
224	  result: {
225	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
226	  },
227	  state: withPolicy(
228	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
229	    stepIndex,
230	    openPolicy(step.items),
231	  ),
232	});
233	
234	// Claim-side enchantment rule (threshold 8), distinct from the premium-side
235	// high-enchantment surcharge (threshold 5).
236	const qualifiesForReducedReimbursement = (item: Item): boolean =>
237	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
238	
239	// Damage to heavily enchanted items is reimbursed at 50 % of the damage amount.
240	//
241	// The spec's other claim rule — "damage to items made of dragon material is
242	// fully reimbursed" — needs no code here, and its absence is not an oversight.
243	// Full reimbursement is already the default for items no clause applies to, so
244	// the dragon rule can only bite where it overrides something; and in the one
245	// case where the two compete (dragon material at enchantment >= 8) the spec
246	// gives the 50 % rule priority. Under the current rules no input distinguishes
247	// an implementation that reads `material` from one that ignores it, which is
248	// why `Item.material` is carried in the schema but never consulted. Adding any
249	// further clause that reimburses below 100 % would change that: dragon material
250	// would then have something to override, and this would need real code.
251	const reimbursementRate = (item: Item): number =>
252	  qualifiesForReducedReimbursement(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
253	
254	// A damage entry together with the specific insured item it was matched to.
255	interface MatchedDamage {
256	  damage: Damage;
257	  item: Item;
258	}
259	
260	// What a single damage entry entitles the claimant to, before the policy-wide
261	// cap is applied. A deductible applies per damage event, i.e. once per damaged
262	// item. Special clauses reduce the reimbursement first; the deductible comes
263	// off after.
264	//
265	// A damage smaller than the deductible yields a negative entitlement. The
266	// payout as a whole is floored at zero in `settleAgainstCap`, so a claim never
267	// bills the claimant, but this per-damage figure stays signed.
268	//
269	// UNSPECIFIED: whether such a damage should offset the others in the same
270	// claim. Because the entitlement stays signed, a 500 G and a 50 G damage
271	// currently pay 350 rather than 400. The spec's examples are all well above
272	// the deductible, so nothing pins this; flooring here instead of per claim
273	// would pick the other reading. Left signed rather than guessing.
274	const damageEntitlement = ({ damage, item }: MatchedDamage): number =>
275	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
276	
277	// Pairs each damage entry with a distinct insured item of the same type: two
278	// damages to "sword" refer to two different insured swords, not the same one
279	// twice. Instances of a type are consumed in the order they were insured.
280	const matchDamagesToItems = (
281	  insuredItems: Item[],
282	  damages: Damage[],
283	): MatchedDamage[] => {
284	  const unclaimed = [...insuredItems];
285	  return damages.map((damage) => {
286	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
287	    if (index === -1) {
288	      throw new Error(`the policy does not cover a damaged ${damage.itemType}`);
289	    }
290	    return { damage, item: unclaimed.splice(index, 1)[0] };
291	  });
292	};
293	
294	// Reading a policy the scenario never opened is a programming error rather
295	// than a claimant's mistake, so this says so plainly instead of asserting the
296	// lookup succeeded and failing later with an incidental TypeError. Validating
297	// the claim step's policy index against the scenario is a separate concern,
298	// still to be specified.
299	const policyFor = (state: ScenarioState, policyId: number): Policy => {
300	  const policy = state.policies.get(policyId);
301	  if (policy === undefined) {
302	    throw new Error(`there is no policy ${policyId}`);
303	  }
304	  return policy;
305	};
306	
307	// The MHPCO does not reimburse a negative loss.
308	const rejectNegativeAmounts = (damages: Damage[]): void => {
309	  const negative = damages.find((damage) => damage.amount < 0);
310	  if (negative !== undefined) {
311	    throw new Error(
312	      `damage amount ${negative.amount} for ${negative.itemType} is negative`,
313	    );
314	  }
315	};
316	
317	// What the matched damages entitle the claimant to, before the policy-wide cap.
318	const claimEntitlement = (matchedDamages: MatchedDamage[]): number =>
319	  matchedDamages.reduce(
320	    (total, matched) => total + damageEntitlement(matched),
321	    0,
322	  );
323	
324	// The total payout per policy is capped: a claim gets at most what is left of
325	// the cap, and whatever it takes is no longer available to later claims. Both
326	// figures are derived here so they cannot drift apart.
327	const settleAgainstCap = (
328	  entitlement: number,
329	  remainingCap: number,
330	): ClaimResult => {
331	  // Payouts round down, in the MHPCO's favour: an entitlement of 350.5 pays
332	  // 350. The floor is applied to the entitlement, which is the only fractional
333	  // input here — `remainingCap` is always whole, starting at twice the
334	  // insurance sum and only ever losing whole payouts.
335	  //
336	  // Clamped to zero at the bottom as well as to the cap at the top: damages
337	  // under the deductible must not bill the claimant, nor hand the policy back
338	  // cap it had already spent.
339	  const payout = Math.max(0, Math.min(Math.floor(entitlement), remainingCap));
340	  return { payout, remainingCap: remainingCap - payout };
341	};
342	
343	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
344	  const policy = policyFor(state, step.policy);
345	  rejectNegativeAmounts(step.incident.damages);
346	  const matchedDamages = matchDamagesToItems(
347	    policy.items,
348	    step.incident.damages,
349	  );
350	  const result = settleAgainstCap(
351	    claimEntitlement(matchedDamages),
352	    policy.remainingCap,
353	  );
354	  return {
355	    result,
356	    state: withPolicy(state, step.policy, {
357	      ...policy,
358	      remainingCap: result.remainingCap,
359	    }),
360	  };
361	};
362	
363	const runStep = (
364	  step: Step,
365	  state: ScenarioState,
366	  stepIndex: number,
367	): StepOutcome => {
368	  switch (step.op) {
369	    case "quote":
370	      return quote(step, state, stepIndex);
371	    case "claim":
372	      return claim(step, state);
373	  }
374	};
375	
376	// Where a scenario stands before any of its steps have run.
377	const initialState = (customer: Customer): ScenarioState => ({
378	  customer,
379	  contractsSoFar: 0,
380	  policies: new Map(),
381	});
382	
383	// The scenario part-way through: the results reported so far, and the state
384	// the next step will be run against.
385	interface ScenarioProgress {
386	  results: Result[];
387	  state: ScenarioState;
388	}
389	
390	// Each step is priced against the state the steps before it established, so
391	// the walk is sequential: fold the steps, threading the state from one to the
392	// next and collecting one result per step. The results array therefore mirrors
393	// the input steps in length and order.
394	export const runScenario = (scenario: Scenario): ScenarioResult => {
395	  const { results } = scenario.steps.reduce<ScenarioProgress>(
396	    ({ results, state }, step, stepIndex) => {
397	      const outcome = runStep(step, state, stepIndex);
398	      return { results: [...results, outcome.result], state: outcome.state };
399	    },
400	    { results: [], state: initialState(scenario.customer) },
401	  );
402	  return { results };
403	};
