1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) {
6	    chunks.push(chunk as Buffer);
7	  }
8	  return Buffer.concat(chunks).toString("utf8");
9	};
10	
11	// The CLI's input contract: one JSON-encoded Scenario on stdin.
12	const readScenario = async (): Promise<Scenario> =>
13	  JSON.parse(await readStdin()) as Scenario;
14	
15	// A rejected scenario produces an error description on stderr and a non-zero
16	// exit status — never a partial `results` document on stdout. Nothing is
17	// written until the whole document exists, so a rejection part-way through a
18	// scenario cannot leave earlier steps' results already on the wire.
19	const main = async (): Promise<void> => {
20	  let report: string;
21	  try {
22	    report = JSON.stringify(runScenario(await readScenario()));
23	  } catch (error) {
24	    process.stderr.write(`${(error as Error).message}\n`);
25	    process.exitCode = 1;
26	    return;
27	  }
28	  process.stdout.write(report);
29	};
30	
31	await main();
