1	import { describe, it, expect } from "vitest";
2	import { execFile } from "node:child_process";
3	import { fileURLToPath } from "node:url";
4	
5	const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));
6	
7	interface CliRun {
8	  stdout: string;
9	  stderr: string;
10	  code: number;
11	}
12	
13	const runCli = (input: string): Promise<CliRun> =>
14	  new Promise((resolve) => {
15	    const child = execFile(
16	      "npx",
17	      ["tsx", CLI],
18	      (error, stdout, stderr) => {
19	        resolve({ stdout, stderr, code: error?.code === undefined ? 0 : Number(error.code) });
20	      },
21	    );
22	    child.stdin?.end(input);
23	  });
24	
25	describe("claim-office CLI", () => {
26	  it("reads a scenario from stdin and writes results to stdout", async () => {
27	    const scenario = {
28	      customer: { yearsWithMHPCO: 5 },
29	      steps: [
30	        {
31	          op: "quote",
32	          items: [
33	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
34	          ],
35	        },
36	        {
37	          op: "claim",
38	          policy: 0,
39	          incident: {
40	            cause: "fire",
41	            damages: [{ itemType: "amulet", amount: 200 }],
42	          },
43	        },
44	      ],
45	    };
46	
47	    const { stdout, code } = await runCli(JSON.stringify(scenario));
48	
49	    // premium: 60 base − 12 loyalty + 6 first insurance + 5 fee = 59
50	    // claim: 200 − 100 deductible = 100; cap 1200 − 100 = 1100
51	    expect(JSON.parse(stdout)).toEqual({
52	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
53	    });
54	    expect(code).toBe(0);
55	  });
56	
57	  it("exits non-zero, writes to stderr, and writes no results when a quote has an unknown item type", async () => {
58	    const scenario = {
59	      customer: { yearsWithMHPCO: 0 },
60	      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
61	    };
62	
63	    const { stdout, stderr, code } = await runCli(JSON.stringify(scenario));
64	
65	    expect(code).not.toBe(0);
66	    expect(stdout).toBe("");
67	    // an error description, not a Node crash dump with a stack trace
68	    expect(stderr.trim()).toBe(
69	      "the MHPCO does not insure items of type broomstick",
70	    );
71	  });
72	  it("rejects the whole run when a later claim is not covered, writing no partial results", async () => {
73	    const scenario = {
74	      customer: { yearsWithMHPCO: 0 },
75	      steps: [
76	        {
77	          op: "quote",
78	          items: [{ type: "sword", material: "steel", enchantment: 3 }],
79	        },
80	        {
81	          op: "claim",
82	          policy: 0,
83	          incident: {
84	            cause: "fire",
85	            damages: [{ itemType: "amulet", amount: 200 }],
86	          },
87	        },
88	      ],
89	    };
90	
91	    const { stdout, stderr, code } = await runCli(JSON.stringify(scenario));
92	
93	    expect(code).not.toBe(0);
94	    expect(stderr.trim()).toBe("the policy does not cover a damaged amulet");
95	    // step 0 quoted successfully, but nothing is written on rejection
96	    expect(stdout).toBe("");
97	  });
98	});
