70	
71	      // 50 G base + 5 G first insurance + 5 G fee
72	      expect(result.results).toEqual([{ premium: 60 }]);
73	    });
74	    it("3 runes → 60 G base premium (block applies)", () => {
75	      const result = runScenario({
76	        customer: { yearsWithMHPCO: 0 },
77	        steps: [
78	          {
79	            op: "quote",
80	            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
81	          },
82	        ],
83	      });
